// 1. Extraemos el texto plano de la cola y lo "despertamos" a JSON real
const textoMensaje = $input.first().json.content;
let datos = JSON.parse(textoMensaje);

// ==========================================
// TRANSFORMACIÓN 1: Limpieza y Formateo
// ==========================================
// Separamos la fecha y la hora en dos columnas distintas 
// para que luego sea más fácil agruparlas en el Data Lake.
let partesFecha = datos.fecha_hora.split("T");
datos.fecha = partesFecha[0]; // "2026-05-06"
datos.hora = partesFecha[1];  // "04:00"

// Redondeamos las coordenadas para quitar ruido
datos.latitud = Math.round(datos.latitud * 1000) / 1000;
datos.longitud = Math.round(datos.longitud * 1000) / 1000;


// ==========================================
// TRANSFORMACIÓN 2: Lógica de Negocio (Alertas)
// ==========================================
// Definimos umbrales de peligrosidad
let limiteNO2 = 40;  
let limitePM10 = 45; 

// Creamos un campo nuevo booleano (True/False)
if (datos.no2 > limiteNO2 || datos.pm10 > limitePM10) {
    datos.alerta_contaminacion = true;
    datos.motivo_alerta = "Alerta activa";
} else {
    datos.alerta_contaminacion = false;
    datos.motivo_alerta = "Ninguno";
}

// 2. Devolvemos el JSON enriquecido
return [ { json: datos } ];

// 1. Recogemos los datos que ya vienen limpios del nodo anterior
let entrada = $input.first().json;

// 2. Lookup: Diccionario de coordenadas a distritos de Madrid
const distritos = {
    "40.41,-3.70": "Centro / Sol",
    "40.42,-3.68": "Salamanca / Retiro",
    "40.40,-3.70": "Arganzuela",
    "40.45,-3.69": "Tetuán / Cuzco"
};

// Generamos la clave redondeando a 2 decimales para que coincida
let clave = `${entrada.latitud.toFixed(2)},${entrada.longitud.toFixed(2)}`;
let nombre_distrito = distritos[clave] || "Área Metropolitana";

// 3. Denormalización: Creamos el objeto final SOLO con lo que importa a negocio
let resumen = {
    fecha: entrada.fecha,
    hora: entrada.hora,
    distrito: nombre_distrito,
    alerta_activa: entrada.alerta_contaminacion,
    motivo: entrada.motivo_alerta
};

// Devolvemos el objeto ligero
return [ { json: resumen } ];
